#include <stdint.h>

#define RCC_BASE 	0x40023800UL
#define RCC_AHB1ENR	(*((volatile uint32_t *)(RCC_BASE + 0x30)))
#define RCC_APB1ENR (*((volatile uint32_t *)(RCC_BASE + 0x40)))

#define GPIOD_BASE    0x40020C00UL
#define GPIOD_MODER   (*((volatile uint32_t *)(GPIOD_BASE + 0x00)))
#define GPIOD_AFRH    (*((volatile uint32_t *)(GPIOD_BASE + 0x24)))

#define SYSTICK_BASE	0xE000E010UL
#define SYSTICK_CTRL	(*((volatile uint32_t *)(0xE000E010UL + 0x00)))
#define SYSTICK_LOAD	(*((volatile uint32_t *)(SYSTICK_BASE + 0x04)))
#define SYSTICK_VAL		(*((volatile uint32_t *)(SYSTICK_BASE + 0x08)))

#define TIM4_BASE     0x40000800UL
#define TIM4_CR1      (*((volatile uint32_t *)(TIM4_BASE + 0x00)))
#define TIM4_ARR      (*((volatile uint32_t *)(TIM4_BASE + 0x2C)))
#define TIM4_PSC      (*((volatile uint32_t *)(TIM4_BASE + 0x28)))
#define TIM4_CCR1     (*((volatile uint32_t *)(TIM4_BASE + 0x34)))
#define TIM4_CCR2     (*((volatile uint32_t *)(TIM4_BASE + 0x38)))
#define TIM4_CCR3     (*((volatile uint32_t *)(TIM4_BASE + 0x3C)))
#define TIM4_CCR4     (*((volatile uint32_t *)(TIM4_BASE + 0x40)))
#define TIM4_CCMR1    (*((volatile uint32_t *)(TIM4_BASE + 0x18)))
#define TIM4_CCMR2    (*((volatile uint32_t *)(TIM4_BASE + 0x1C)))
#define TIM4_CCER     (*((volatile uint32_t *)(TIM4_BASE + 0x20)))
#define TIM4_EGR      (*((volatile uint32_t *)(TIM4_BASE + 0x14)))

volatile uint32_t tick = 0;

void SysTick_Handler(void) {tick++;}

void delay_ms(uint32_t ms) {
	uint32_t start = tick;
	while ((tick - start) < ms);
}

int main(void)
{
	SYSTICK_LOAD = 16000 - 1;
	SYSTICK_VAL = 0;
	SYSTICK_CTRL = 0x7;

	RCC_AHB1ENR |= (1 << 3);   // GPIOD
	RCC_APB1ENR |= (1 << 2);   // TIM4

	// 3. PD12 設為 AF mode
	GPIOD_MODER &= ~(0x3 << (12 * 2));
	GPIOD_MODER |=  (0x2 << (12 * 2));

	GPIOD_MODER &= ~(0x3 << (13 * 2));
	GPIOD_MODER |=  (0x2 << (13 * 2));

	GPIOD_MODER &= ~(0x3 << (14 * 2));
	GPIOD_MODER |=  (0x2 << (14 * 2));

	GPIOD_MODER &= ~(0x3 << (15 * 2));
	GPIOD_MODER |=  (0x2 << (15 * 2));

	// 4. PD12 選 AF2（TIM4_CH1）
	GPIOD_AFRH &= ~(0xF << ((12 - 8) * 4));
	GPIOD_AFRH |=  (0x2 << ((12 - 8) * 4));

	GPIOD_AFRH &= ~(0xF << ((13 - 8) * 4));
	GPIOD_AFRH |=  (0x2 << ((13 - 8) * 4));

	GPIOD_AFRH &= ~(0xF << ((14 - 8) * 4));
	GPIOD_AFRH |=  (0x2 << ((14 - 8) * 4));

	GPIOD_AFRH &= ~(0xF << ((15 - 8) * 4));
	GPIOD_AFRH |=  (0x2 << ((15 - 8) * 4));

	// 5. TIM4 設定
	// PSC=15, ARR=999 → PWM 頻率 = 16MHz / (15+1) / (999+1) = 1kHz
	TIM4_PSC  = 15;
	TIM4_ARR  = 999;
	TIM4_CCR1 = 0;   // 初始 duty cycle = 0%
	TIM4_CCR2 = 0;
	TIM4_CCR3 = 0;
	TIM4_CCR4 = 0;

	// 6. CH1 設為 PWM mode 1（CCMR1 bit[6:4] = 110）
	TIM4_CCMR1 &= ~(0x7 << 4);
	TIM4_CCMR1 |=  (0x6 << 4);
	TIM4_CCMR1 |=  (1 << 3);   // OC1PE：preload enable

	TIM4_CCMR1 &= ~(0x7 << 12);
	TIM4_CCMR1 |=  (0x6 << 12);
	TIM4_CCMR1 |=  (1 << 11);   // OC1PE：preload enable

	TIM4_CCMR2 &= ~(0x7 << 4);
	TIM4_CCMR2 |=  (0x6 << 4);
	TIM4_CCMR2 |=  (1 << 3);   // OC1PE：preload enable

	TIM4_CCMR2 &= ~(0x7 << 12);
	TIM4_CCMR2 |=  (0x6 << 12);
	TIM4_CCMR2 |=  (1 << 11);   // OC1PE：preload enable

	// 7. 開啟 CH1 輸出
	TIM4_CCER |= (1 << 0);
	TIM4_CCER |= (1 << 4);
	TIM4_CCER |= (1 << 8);
	TIM4_CCER |= (1 << 12);

	// 8. 產生 update event，讓 PSC/ARR 生效
	TIM4_EGR |= (1 << 0);

	// 9. 啟動 TIM4
	TIM4_CR1 |= (1 << 0);

	// 呼吸燈：CCR1 從 0 漸增到 999，再漸減回 0
	int ccr = 0;
	int dir = 1;   // 1=漸亮, -1=漸暗

	while (1) {
		ccr += dir;
		if (ccr >= 999) dir = -1;
		if (ccr <= 0) dir = 1;

		TIM4_CCR1 = ccr;
		TIM4_CCR2 = ccr;
		TIM4_CCR3 = ccr;
		TIM4_CCR4 = ccr;
		delay_ms(1);
	}
}
